def solve(s, words):
    w = set(words)
    n = len(s)
    dp = [True] + [False] * n
    for i in range(1, n + 1):
        for j in range(i):
            if dp[j] and s[j:i] in w:
                dp[i] = True
                break
    return dp[n]

word-break.java:
import java.util.*;
class Solution {
    boolean solve(String s, String[] words) {
        Set<String> w = new HashSet<>(Arrays.asList(words));
        int n = s.length(); boolean[] dp = new boolean[n + 1]; dp[0] = true;
        for (int i = 1; i <= n; i++)
            for (int j = 0; j < i; j++)
                if (dp[j] && w.contains(s.substring(j, i))) { dp[i] = true; break; }
        return dp[n];
    }
}

